update ai_call_dial_log
trunk_id = #{trunkId}, trunk_code = #{trunkCode}, trunk_carrier = #{trunkCarrier}, line_type = #{lineType}, route_strategy = #{routeStrategy}, failover_count = #{failoverCount}, failover_trunks = #{failoverTrunks}, queue_wait_ms = #{queueWaitMs}, dial_status = #{dialStatus}, hangup_cause = #{hangupCause}, sip_code = #{sipCode}, fail_reason = #{failReason}, ring_time = #{ringTime}, answer_time = #{answerTime}, hangup_time = #{hangupTime}, ring_duration = #{ringDuration}, talk_duration = #{talkDuration}, total_duration = #{totalDuration}, bill_duration = #{billDuration}, is_connected = #{isConnected}, mos = #{mos}, packet_loss = #{packetLoss}, jitter = #{jitter}, rtt = #{rtt}, record_file = #{recordFile}, record_id = #{recordId}, callee_id = #{calleeId}, update_by = #{updateBy}, remark = #{remark}, update_time = sysdate()
