mapper.select:
select count(1)                                              as totalCalls,
       sum(case when is_connected = '1' then 1 else 0 end)   as connectedCalls,
       ifnull(round(sum(case when is_connected = '1' then 1 else 0 end) * 100 / nullif(count(1), 0), 2), 0) as connectRate,
       ifnull(round(sum(talk_duration) / nullif(sum(case when is_connected = '1' then 1 else 0 end), 0)), 0) as acd,
       ifnull(round(avg(nullif(mos, 0)), 2), 0)              as avgMos
from ai_call_dial_log
where trunk_id = #{trunkId}
  and dial_time >= #{beginTime}
  and dial_time < #{endTime}
